#!/usr/bin/env bash
# step197 — rebuild About page (consistent measure) + fix storefront btn-g (trials stray buttons).
set -uo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
cd "$GSZ" || { echo "FATAL: no $GSZ"; exit 1; }

FILES=(views/about.ejs public/css/app.css views/partials/store_top.ejs)
for f in "${FILES[@]}"; do cp -p "$f" "$f.bak-step197-$TS"; done
echo "backups: *.bak-step197-$TS"

restore(){ echo "!! restoring from backups"; for f in "${FILES[@]}"; do [ -f "$f.bak-step197-$TS" ] && cp -p "$f.bak-step197-$TS" "$f"; done; }
trap 'restore' ERR

PJS=$(mktemp /tmp/patch_step197.XXXXXX.js)
base64 -d > "$PJS" <<'B64EOF'

B64EOF
node "$PJS" "$GSZ"

# --- validate BOTH edited views compile against the real partials ---
node -e "const ejs=require('$GSZ/node_modules/ejs'),fs=require('fs');['views/about.ejs','views/partials/store_top.ejs'].forEach(function(f){ejs.compile(fs.readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('ejs ok: '+f);});" || { echo 'EJS COMPILE FAILED'; restore; exit 2; }

# --- verify edits landed ---
grep -q 'class="aboutpg"' views/about.ejs || { echo 'VERIFY FAILED: aboutpg not present'; restore; exit 3; }
grep -q '.btn-ghost,.btn-g{background:var(--surface)' public/css/app.css || { echo 'VERIFY FAILED: btn-g alias missing'; restore; exit 3; }
grep -q 'app.css?v=27' views/partials/store_top.ejs || { echo 'VERIFY FAILED: cache-buster not bumped'; restore; exit 3; }
echo "verify ok: aboutpg + btn-g alias + v=27"

trap - ERR

pm2 restart gsz --update-env >/dev/null 2>&1 || pm2 restart gsz >/dev/null 2>&1
ok=0
for i in $(seq 1 25); do
  code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
  if [ "$code" = "200" ]; then ok=1; echo "health ok (HTTP 200) after ${i} tries"; break; fi
  sleep 0.6
done
[ "$ok" = "1" ] || { echo "HEALTH CHECK FAILED (last: ${code:-none}) — restoring"; restore; pm2 restart gsz >/dev/null 2>&1; exit 4; }

# --- quick sanity: About page serves 200 too ---
acode=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/about || true)
echo "about page: HTTP $acode"

echo "STEP197 DONE — About page unified; trials secondary buttons fixed."
